

class ValueProperty(object):
    def __init__(self, value, operator='==', regex=False):
        self.value = value
        self.operator = operator
        self.regex = regex

    def __str__(self):
        return r"VALUE: '{}', OPERATOR: '{}', REGEX: '{}'".format(self.value, self.operator, self.regex)


